# -*- coding: utf-8 -*-
# Phan D: muc 5 — 3 hinh dang mat bang
D = []
P = D.append

P(('h2','5. Mẫu thiết kế văn phòng 70m2 theo hình dạng mặt bằng'))
P(('p','Phong cách là thứ doanh nghiệp được chọn. Hình dạng mặt bằng thì không — nó đã có sẵn khi ký hợp đồng thuê. Ba dạng dưới đây là ba hình dạng 70m² hay gặp nhất, tương ứng với ba sơ đồ ở mục 3. Với mỗi dạng, phần quan trọng nhất là **dạng đó ép doanh nghiệp phải bỏ gì** để đủ chỗ ngồi.'))

# ---------- 5.1 HEP DAI ----------
P(('h3','5.1. Mẫu văn phòng 70m2 mặt bằng hẹp và dài'))
P(('p','Đây là dạng mặt bằng phổ biến nhất trong các tòa văn phòng cho thuê, thường có tỷ lệ từ 1:2,5 đến 1:4 — ví dụ 14m × 5m hoặc 17,5m × 4m. Cửa vào nằm ở một đầu, cửa sổ chạy dọc một hoặc hai mặt dài. Cách bố trí gần như bắt buộc là: hai phòng kín ở hai đầu, khu làm việc chung ở giữa, lối đi chạy suốt theo trục dài.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Phân khu rất rõ ràng.** Khách vào một đầu, khu nội bộ ở đầu kia, hai luồng không cắt nhau.',
  '**Mặt kính dài.** Cửa sổ chạy suốt cạnh dài nên ánh sáng tự nhiên phân bố đều cho cả dãy bàn.',
  '**Dễ kê bàn thẳng dãy.** Bàn xếp thành hai dãy dọc trục là cách kê đơn giản và ít lãng phí góc nhất.',
  '**Phòng giám đốc và phòng họp tách xa nhau.** Tiếng họp không lọt sang phòng lãnh đạo.']))
P(('p','Theo sơ đồ 1 ở trên (14m × 5m), lối đi chính rộng 1,2m phải chạy suốt 8,8m, tức chiếm gần 11m² tính cả phần dẫn vào hai phòng đầu hồi — nhiều hơn hẳn hai dạng còn lại. Nghiêm trọng hơn: chiều sâu khu làm việc chung chỉ còn 3,6m, vừa đủ cho đúng hai dãy bàn. Kết quả là 10 chỗ ngồi, ít nhất trong ba dạng.'))
P(('p','**Phải bỏ gì:** dạng này buộc doanh nghiệp bỏ ý định làm dãy bàn thứ ba, hoặc bỏ pantry riêng để đổi lấy thêm chỗ ngồi. Nếu bắt buộc phải đủ 12 chỗ, cách khả thi nhất là bỏ phòng họp kín và chuyển sang họp tại bàn dài ở khu tiếp khách.'))
P(('img','a70-12','Mặt bằng văn phòng 70m2 dạng hẹp và dài — phòng kín dồn về hai đầu, khu làm việc chung chạy dọc trục giữa'))
P(('img','a70-14','Mặt bằng 70m2 tỷ lệ 17,5m × 4m — dạng hẹp dài cực đoan, khu làm việc chung chỉ xếp được một dãy bàn kép'))
P(('img','a70-18','Bố trí mặt bằng văn phòng 70m2 dạng 14m × 5m, quầy lễ tân đặt ngay cửa vào để tách luồng khách khỏi khu làm việc'))
P(('img','b80-03','Phòng dài hẹp với dãy cửa sổ chạy suốt một cạnh — ánh sáng tự nhiên đều cho cả dãy bàn (Ảnh tham khảo)'))
P(('img','b80-29','Bàn kê thẳng dãy dọc trục dài, lối đi chạy suốt một bên — cách kê ít lãng phí góc nhất (Ảnh tham khảo)'))

# ---------- 5.2 VUONG ----------
P(('h3','5.2. Mẫu văn phòng 70m2 mặt bằng vuông cân xứng'))
P(('p','Mặt bằng vuông hoặc gần vuông có tỷ lệ từ 1:1 đến 1:1,3 — với 70m² thường là 8,4m × 8,4m hoặc 9m × 8m. Đây là dạng dễ quy hoạch nhất: khu làm việc chung đặt ở trung tâm hoặc chiếm trọn một nửa, các phòng chức năng xếp dọc một hoặc hai cạnh, lối đi chỉ cần một trục thẳng.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Nhiều chỗ ngồi nhất trong ba dạng.** Khu làm việc sâu trên 6m nên xếp được bốn dãy bàn thay vì hai.',
  '**Lối đi ngắn nhất.** Một trục thẳng phục vụ cả mặt bằng, không phải chạy vòng.',
  '**Chia khu cân đối.** Các phòng chức năng có thể xếp đối xứng nên bản vẽ gọn và dễ thi công.',
  '**Dễ mở rộng về sau.** Thêm một dãy bàn không phá vỡ bố cục tổng thể.']))
P(('p','Theo sơ đồ 2 (8,4m × 8,4m), khu làm việc chung sâu 6,4m. Mỗi dãy bàn cần khoảng 1,3m chiều sâu tính cả ghế, nên 6,4m xếp được bốn dãy — gấp đôi dạng hẹp dài. Với ba chỗ mỗi dãy, mặt bằng cho ra 12 chỗ ngồi mà vẫn giữ đủ lễ tân 8,3m², phòng giám đốc 7,7m², pantry 3,8m² và phòng họp 6 chỗ. Lối đi chỉ chiếm khoảng 11,8m², và phần lớn là trục chính có ích chứ không phải hành lang cụt.'))
P(('p','**Phải bỏ gì:** đổi lại, mặt bằng vuông thường chỉ có một hoặc hai mặt tiếp xúc cửa sổ, nên vị trí ngồi ở giữa sàn sẽ thiếu sáng tự nhiên. Doanh nghiệp phải chấp nhận bỏ tiêu chí "ai cũng gần cửa sổ", bù bằng hệ đèn đủ 400 – 500 lux trên mặt bàn và tránh dùng vách cao chắn sáng.'))
P(('img','a70-13','Mặt bằng văn phòng 70m2 dạng vuông cân xứng 8,37m × 8,37m — khu làm việc chung ở giữa, phòng chức năng xếp quanh'))
P(('img','a70-22','Phối cảnh từ trên xuống của mặt bằng 70m2 vuông: khu làm việc chung chiếm trọn một nửa, phòng kín dồn về một cạnh'))
P(('img','b80-01','Bàn kê dọc tường kính, phòng họp ốp gỗ sát lối đi — cách chia khu quen thuộc của mặt bằng vuông (Ảnh tham khảo)'))
P(('img','b80-12','Tủ hồ sơ âm tường chạy suốt một mặt tường, giải phóng sàn cho chỗ ngồi (Ảnh tham khảo)'))
P(('img','b80-35','Khu làm việc tập trung giữa phòng, hệ tủ và kệ dồn hết vào tường bao (Ảnh tham khảo)'))

# ---------- 5.3 LO GOC ----------
P(('h3','5.3. Mẫu văn phòng 70m2 mặt bằng lô góc'))
P(('p','Lô góc là mặt bằng nằm ở góc tòa nhà, có hai mặt tiếp xúc cửa sổ vuông góc nhau — với 70m² thường là 10m × 7m. Đây là dạng sáng nhất và có giá thuê cao nhất trong ba dạng. Bài toán riêng của nó là điểm giao hai bức tường: nếu không xử lý, góc này thành góc chết không dùng được vào việc gì.'))
P(('lead','Ưu điểm với mặt bằng 70m²'))
P(('ul',[
  '**Ánh sáng tự nhiên tốt nhất.** Hai mặt kính nghĩa là sáng gần như cả ngày, ít phải bật đèn.',
  '**Có vị trí đắt giá để tiếp khách.** Góc hai mặt kính là chỗ gây ấn tượng mạnh nhất với đối tác.',
  '**Cảm giác rộng hơn diện tích thật.** Tầm nhìn ra ngoài ở hai hướng làm mặt bằng 70m² bớt cảm giác đóng.',
  '**Thông gió tự nhiên tốt hơn.** Cửa sổ hai hướng cho phép tạo luồng khí đối lưu.']))
P(('p','Theo sơ đồ 3 (10m × 7m), phòng giám đốc 8,3m² đặt đúng vào góc hai mặt kính và phòng họp 8,8m² nằm ngay dưới. Hai phòng này chiếm trọn cạnh có view đẹp nhất, đẩy khu làm việc chung 29m² vào phần trong. Kết quả là 11 chỗ ngồi — nhiều hơn dạng hẹp dài nhưng vẫn ít hơn dạng vuông một chỗ, dù diện tích y hệt.'))
P(('p','**Phải bỏ gì:** dạng này ép doanh nghiệp chọn dứt khoát ai được ngồi ở góc đẹp. Nếu ưu tiên lãnh đạo và khách, khu làm việc chung mất phần sáng nhất. Nếu ưu tiên nhân sự, phòng giám đốc phải lùi vào trong và mất lợi thế view. Ngoài ra, hai mặt kính đồng nghĩa ít tường đặc để kê tủ hồ sơ — hệ lưu trữ buộc phải dồn vào một cạnh hoặc chuyển sang tủ thấp dưới bệ cửa sổ.'))
P(('img','a70-02','Phối cảnh mặt bằng văn phòng 70m2 lô góc — nhiều mặt kính, phòng kín dồn về phía trong để giữ sáng cho khu chung'))
P(('img','b80-16','Vách kính khung thép đen ở góc phòng — giữ được tầm nhìn hai hướng khi chia phòng riêng (Ảnh tham khảo)'))
P(('img','b80-26','Góc hai mặt cửa sổ lớn dùng làm khu tiếp khách, khai thác đúng vị trí đắt giá nhất của lô góc (Ảnh tham khảo)'))
P(('img','b80-27','Khu tiếp khách đặt sát dãy cửa sổ hai mặt, tận dụng ánh sáng tự nhiên thay cho đèn (Ảnh tham khảo)'))
P(('img','b80-42','Trần lam gỗ và bàn màu nhấn ở khu ven cửa sổ — cách làm ấm mặt bằng nhiều kính (Ảnh tham khảo)'))
